import type {
  Column as TableColumn,
  ColumnDef,
  Header as TableHeader,
  HeaderGroup as TableHeaderGroup,
  ReactTable,
  Row as TableRow,
  RowData,
  TableOptions,
} from '@tanstack/react-table'
import {
  columnOrderingFeature,
  columnPinningFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  createExpandedRowModel,
  createPaginatedRowModel,
  flexRender,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSortingFeature,
  tableFeatures,
  useTable,
} from '@tanstack/react-table'
import { Loader2, SearchX } from 'lucide-react'
import type { CSSProperties, MouseEvent as ReactMouseEvent, ReactNode } from 'react'
import { Fragment, useEffect, useState } from 'react'

import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Table as TablePrimitive,
  TableBody as TableBodyPrimitive,
  TableCell,
  TableHead as TableHeadPrimitive,
  TableHeader as TableHeaderPrimitive,
  TableRow as TableRowPrimitive,
} from '@/components/ui/table'
import { cn } from '@/lib/utils'

import { EmptyState } from '../empty-state'
import type { ColumnMeta, FilterContext } from './column-filter'
import { ColumnFilter } from './column-filter'
import { PaginationControls, type PaginationControlsLabels } from './pagination'

const dataTableFeatures = tableFeatures({
  columnOrderingFeature,
  columnPinningFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSortingFeature,
  expandedRowModel: createExpandedRowModel(),
  // Without a paginated row model TanStack v9 hands back every row, so a local (non-manual)
  // table would render the whole dataset under a footer that claims one page of it.
  paginatedRowModel: createPaginatedRowModel(),
})

/** @internal TanStack v9 threads this exact feature set through its invariant types. */
export type DataTableFeatures = typeof dataTableFeatures
export type {
  ColumnFilterMeta,
  ColumnMeta,
  FilterContext,
  FilterOption,
  FilterValues,
} from './column-filter'
type Table<TData extends RowData> = ReactTable<DataTableFeatures, TData>
type Column<TData extends RowData, TValue = unknown> = TableColumn<DataTableFeatures, TData, TValue>
type Header<TData extends RowData, TValue = unknown> = TableHeader<DataTableFeatures, TData, TValue>
type HeaderGroup<TData extends RowData> = TableHeaderGroup<DataTableFeatures, TData>
type Row<TData extends RowData> = TableRow<DataTableFeatures, TData>

/** Private timing detail of DataTable; app code should never depend on it. */
function useDelayedLoading(isLoading: boolean, delayMs = 150) {
  const [showLoading, setShowLoading] = useState(isLoading && delayMs <= 0)

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (!isLoading) {
      setShowLoading(false)
      return
    }
    if (delayMs <= 0) {
      setShowLoading(true)
      return
    }
    setShowLoading(false)
    const timeoutId = globalThis.setTimeout(() => setShowLoading(true), delayMs)
    return () => globalThis.clearTimeout(timeoutId)
  }, [delayMs, isLoading])

  return showLoading
}

export type RowWrapperProps<TData extends RowData> = React.HTMLAttributes<HTMLTableRowElement> & {
  row: Row<TData>
  children: React.ReactNode
}

export type TranslateHeader = (header: string, columnId: string) => ReactNode

// A real row click starts on one of the row's own cells. Anything else reaching
// the row handler came from a portal — Base UI renders dialogs, popovers and menus
// at <body>, but React events still bubble through the React tree, so a click
// inside an overlay opened from a cell arrives here too.
//
// Testing containment rather than "does the target sit inside an overlay" keeps
// the check fail-safe: if the clicked node has already been detached from the
// DOM, containment is false and the row simply does not fire, instead of a
// selector lookup coming back empty and letting the click through.
const startedInsideRow = (event: ReactMouseEvent<HTMLElement>) =>
  event.target instanceof Node && event.currentTarget.contains(event.target)

function getColumnAttributes<TData extends RowData>(column: Column<TData>) {
  const columnSet = [...column.columns, column]
  const isPinned = columnSet.map((c) => c.getIsPinned()).find((p) => p !== false) || false
  const isLastLeftPinnedColumn = columnSet.some(
    (c) => isPinned === 'start' && c.getIsLastColumn('start'),
  )
  const isFirstRightPinnedColumn = columnSet.some(
    (c) => isPinned === 'end' && c.getIsFirstColumn('end'),
  )
  return { isPinned, isLastLeftPinnedColumn, isFirstRightPinnedColumn }
}

function getHeaderAttributes<TData extends RowData, TValue>(
  header: Header<TData, TValue>,
  centerHeaders?: HeaderGroup<TData>[],
) {
  const isColumnId = (group: HeaderGroup<TData>, index: number) => {
    const headers = group?.headers || []
    return headers[index]?.id === header.id || headers[index]?.column?.id === header.column?.id
  }
  const isFirstUnpinnedColumn = centerHeaders?.some(
    (group, index) =>
      (index === 0 && isColumnId(group, 0)) || (index === 1 && isColumnId(group, 0)),
  )
  const isLastUnpinnedColumn = centerHeaders?.some(
    (group, index) =>
      (index === 0 && isColumnId(group, group.headers.length - 1)) ||
      (index === 1 && isColumnId(group, group.headers.length - 1)),
  )
  return { isFirstUnpinnedColumn, isLastUnpinnedColumn }
}

function getBodyAttributes<TData extends RowData, TValue>(
  header: Column<TData, TValue>,
  centerHeaders?: HeaderGroup<TData>[],
) {
  const isFirstUnpinnedColumn = centerHeaders?.some((group) => group.headers[0]?.id === header.id)
  const isLastUnpinnedColumn = centerHeaders?.some(
    (group) => group.headers[group.headers.length - 1]?.id === header.id,
  )
  return { isFirstUnpinnedColumn, isLastUnpinnedColumn }
}

function getCommonPinningStyles<TData extends RowData>(
  column: Column<TData>,
  pinnedIndex: number,
  isShadowTranslatedUpwards?: boolean,
): CSSProperties {
  const { isPinned, isLastLeftPinnedColumn, isFirstRightPinnedColumn } = getColumnAttributes(column)
  const leftValue =
    column.columns.length > 0
      ? `${column.columns[0]?.getStart('start')}px`
      : `${column.getStart('start')}px`
  return {
    boxShadow: isLastLeftPinnedColumn
      ? `8px ${isShadowTranslatedUpwards ? -6 : 8}px 15px 0px #0C71AC14`
      : isFirstRightPinnedColumn
        ? `-8px ${isShadowTranslatedUpwards ? -6 : 8}px 15px 0px #0C71AC14`
        : undefined,
    left: isPinned === 'start' ? leftValue : undefined,
    right: isPinned === 'end' ? `${column.getAfter('end')}px` : undefined,
    position: isPinned ? 'sticky' : 'relative',
    width: column.getSize(),
    zIndex: isPinned ? pinnedIndex : pinnedIndex - 1,
  }
}

function HeaderCell<TData extends RowData>({
  header,
  translateHeader,
}: {
  header: Header<TData, unknown>
  translateHeader?: TranslateHeader
}) {
  const definition = header.column.columnDef.header
  if (translateHeader && typeof definition === 'string') {
    return translateHeader(definition, header.column.id)
  }
  return flexRender(definition, header.getContext())
}

type HeadProps<TData extends RowData> = {
  table: Table<TData>
  filtering?: FilterContext
  translateHeader?: TranslateHeader
}

function TableHead<TData extends RowData>({ table, filtering, translateHeader }: HeadProps<TData>) {
  const totalColumns = table.getAllColumns().length
  const totalLeafColumns = table.getAllLeafColumns().length
  const centerHeaders = table.getCenterHeaderGroups()
  return (
    <TableHeaderPrimitive className="sticky top-0 z-10">
      {table.getHeaderGroups()?.map((headerGroup) => (
        <TableRowPrimitive key={headerGroup.id}>
          {headerGroup.headers.map((header, index) => {
            const { columnDef, parent, columns } = header.column
            const { isLastLeftPinnedColumn, isFirstRightPinnedColumn } = getColumnAttributes(
              header.column,
            )
            const { isFirstUnpinnedColumn, isLastUnpinnedColumn } = getHeaderAttributes(
              header,
              centerHeaders,
            )
            const columnIndex = header.column.getIndex()
            const siblingHeaders = header.column.parent?.columns || []
            const isLastGroupHeader =
              siblingHeaders?.findIndex((h) => h.id === header.id) === siblingHeaders.length - 1
            const meta = columnDef.meta as ColumnMeta | undefined
            const showFilter = !!meta?.filter && !!filtering
            const headerClassName = meta?.headerClassName
            return (
              <TableHeadPrimitive
                colSpan={header.colSpan}
                scope="col"
                key={header.id}
                style={{ ...getCommonPinningStyles(header.column, parent ? 9 : 10, true) }}
                className={cn(
                  'p-0 text-start text-sm font-light text-foreground',
                  headerClassName || 'bg-card',
                  (index === 0 || isFirstRightPinnedColumn) && !parent && 'rounded-ss-panel ps-2',
                  (index === totalColumns - 1 || isLastLeftPinnedColumn) &&
                    !parent &&
                    'rounded-se-panel pe-2',
                )}
              >
                <div
                  className={cn(
                    columns.length ? 'mt-2' : 'my-2 py-2',
                    !!parent && 'my-0 py-0 text-center',
                    (index === 0 || isFirstRightPinnedColumn || isFirstUnpinnedColumn) &&
                      'rounded-s-control',
                    (index === totalColumns - 1 ||
                      isLastLeftPinnedColumn ||
                      isLastUnpinnedColumn) &&
                      'rounded-e-control',
                    !parent && (headerClassName || 'bg-background'),
                    isFirstUnpinnedColumn && index !== 0 && 'ms-2',
                    isLastUnpinnedColumn && index !== totalColumns - 1 && 'me-2',
                  )}
                >
                  <div
                    className={cn(
                      'w-full px-3',
                      showFilter && 'flex justify-between',
                      !!columns.length && 'py-2',
                      !!parent && (isLastGroupHeader ? 'py-2.5' : 'my-1.5 py-0'),
                      !(
                        isLastLeftPinnedColumn ||
                        columnIndex === totalLeafColumns - 1 ||
                        isLastUnpinnedColumn
                      ) && 'border-e',
                    )}
                  >
                    {header.isPlaceholder ? null : (
                      <HeaderCell header={header} translateHeader={translateHeader} />
                    )}
                    {showFilter && <ColumnFilter column={header.column} filtering={filtering} />}
                  </div>
                  <div
                    className={cn(
                      'absolute bottom-0 left-0 right-0 h-[1px] bg-border/60',
                      !parent && 'hidden',
                      (columnIndex === totalLeafColumns - 1 ||
                        isLastLeftPinnedColumn ||
                        isLastUnpinnedColumn) &&
                        'right-2',
                      (columnIndex === 0 || isFirstRightPinnedColumn || isFirstUnpinnedColumn) &&
                        'left-2',
                    )}
                  ></div>
                </div>
              </TableHeadPrimitive>
            )
          })}
        </TableRowPrimitive>
      ))}
    </TableHeaderPrimitive>
  )
}

type BodyProps<TData extends RowData> = {
  table: Table<TData>
  onRowClick?: (row: Row<TData>) => void
  rowClassName?: (row: Row<TData>) => string
  RowWrapper?: React.ComponentType<RowWrapperProps<TData>>
  renderSubComponent?: (props: { row: Row<TData> }) => React.ReactElement
}

function TableBody<TData extends RowData>({
  table,
  onRowClick,
  rowClassName,
  RowWrapper,
  renderSubComponent,
}: BodyProps<TData>) {
  const totalColumns = table.getAllLeafColumns().length
  const pageSize = table.getRowModel().rows.length
  const centerHeaders = table.getCenterHeaderGroups()
  return (
    <TableBodyPrimitive className="text-sm">
      {table.getRowModel()?.rows.map((row, index) => {
        const rowProps = {
          className: cn('group bg-card', !!onRowClick && 'cursor-pointer', rowClassName?.(row)),
          onClick: (event: ReactMouseEvent<HTMLElement>) => {
            // Clicks inside a dialog/popover opened from one of this row's cells would
            // otherwise navigate away underneath the open overlay. DialogContent used to stop
            // propagation itself; it can't any more (see dialog.tsx), so filter by origin here.
            if (!startedInsideRow(event)) return
            if (onRowClick) onRowClick(row)
          },
        }
        const cells = row.getVisibleCells().map((cell) => {
          const { columnDef } = cell.column
          const columnIndex = cell.column.getIndex()
          const { isLastLeftPinnedColumn, isFirstRightPinnedColumn } = getColumnAttributes(
            cell.column,
          )
          const { isFirstUnpinnedColumn, isLastUnpinnedColumn } = getBodyAttributes(
            cell.column,
            centerHeaders,
          )
          const cellClassName = (columnDef.meta as ColumnMeta | undefined)?.cellClassName
          return (
            <TableCell
              key={cell.id}
              style={{ ...getCommonPinningStyles(cell.column, 4) }}
              className={cn(
                'relative min-h-20 p-0',
                !rowClassName && !cellClassName && 'bg-card',
                cellClassName,
                index === pageSize - 1 && isLastLeftPinnedColumn && 'rounded-ee-panel',
                index === pageSize - 1 && isFirstRightPinnedColumn && 'rounded-bl-panel',
              )}
            >
              <div className="w-full p-3 py-2.5">
                {flexRender(columnDef.cell, cell.getContext())}
              </div>
              <div
                className={cn(
                  'absolute bottom-0 left-0 right-0 bg-background',
                  !row.getIsExpanded() && 'h-[1px]',
                  index === pageSize - 1 && 'hidden',
                  (columnIndex === totalColumns - 1 ||
                    isLastLeftPinnedColumn ||
                    isLastUnpinnedColumn) &&
                    'right-2',
                  (columnIndex === 0 || isFirstRightPinnedColumn || isFirstUnpinnedColumn) &&
                    'left-2',
                )}
              ></div>
            </TableCell>
          )
        })
        return (
          <Fragment key={row.id}>
            {RowWrapper ? (
              <RowWrapper row={row} {...rowProps}>
                {cells}
              </RowWrapper>
            ) : (
              <TableRowPrimitive {...rowProps}>{cells}</TableRowPrimitive>
            )}
            {row.getIsExpanded() && !!renderSubComponent && (
              <TableRowPrimitive className="border-b">
                <TableCell colSpan={row.getVisibleCells().length}>
                  {renderSubComponent({ row })}
                </TableCell>
              </TableRowPrimitive>
            )}
          </Fragment>
        )
      })}
    </TableBodyPrimitive>
  )
}

function TableLoadingBody<TData extends RowData>({
  table,
  rowCount,
}: {
  table: Table<TData>
  rowCount: number
}) {
  const columns = table.getVisibleLeafColumns()
  const centerHeaders = table.getCenterHeaderGroups()
  return (
    <TableBodyPrimitive className="text-sm">
      {Array.from({ length: rowCount }).map((_, rowIndex) => (
        <TableRowPrimitive key={`skeleton-row-${rowIndex}`} className="bg-card">
          {columns.map((column, columnIndex) => {
            const { isLastLeftPinnedColumn, isFirstRightPinnedColumn } = getColumnAttributes(column)
            const { isFirstUnpinnedColumn, isLastUnpinnedColumn } = getBodyAttributes(
              column,
              centerHeaders,
            )
            return (
              <TableCell
                key={`skeleton-cell-${column.id}-${rowIndex}`}
                style={{ ...getCommonPinningStyles(column, 4) }}
                className={cn(
                  'relative min-h-20 bg-card p-0',
                  rowIndex === rowCount - 1 && isLastLeftPinnedColumn && 'rounded-ee-panel',
                  rowIndex === rowCount - 1 && isFirstRightPinnedColumn && 'rounded-bl-panel',
                )}
              >
                <div className="w-full p-3 py-2.5">
                  <Skeleton className={cn('h-4', columnIndex === 0 ? 'w-32' : 'w-full')} />
                </div>
                <div
                  className={cn(
                    'absolute bottom-0 left-0 right-0 h-[1px] bg-background',
                    rowIndex === rowCount - 1 && 'hidden',
                    (columnIndex === columns.length - 1 ||
                      isLastLeftPinnedColumn ||
                      isLastUnpinnedColumn) &&
                      'right-2',
                    (columnIndex === 0 || isFirstRightPinnedColumn || isFirstUnpinnedColumn) &&
                      'left-2',
                  )}
                ></div>
              </TableCell>
            )
          })}
        </TableRowPrimitive>
      ))}
    </TableBodyPrimitive>
  )
}

export type DataTableColumn<TData extends RowData> = ColumnDef<DataTableFeatures, TData>
export type { PaginationControlsLabels, PaginationControlsProps } from './pagination'
export { PaginationControls } from './pagination'

type DataTableOptions<TData extends RowData> = Omit<
  TableOptions<DataTableFeatures, TData>,
  'columns' | 'data' | 'features'
>

export type DataTableProps<TData extends RowData> = DataTableOptions<TData> & {
  data: TData[]
  columns: DataTableColumn<TData>[]
  onRowClick?: (row: Row<TData>) => void
  renderSubComponent?: (props: { row: Row<TData> }) => React.ReactElement
  className?: string
  rowClassName?: (row: Row<TData>) => string
  style?: CSSProperties
  loading?: boolean
  loadingMode?: 'skeleton' | 'overlay'
  loadingRowCount?: number
  heightAuto?: boolean
  filtering?: FilterContext
  RowWrapper?: React.ComponentType<RowWrapperProps<TData>>
  translateHeader?: TranslateHeader
  clearFiltersLabel?: string
  loadingLabel?: string
  EmptyComponent?: React.ComponentType
  LoadingComponent?: React.ComponentType
  /**
   * Adds the standard NETIX list footer. Pass `state.pagination` and
   * `onPaginationChange` to make it fully controlled; manual/server tables also
   * pass `rowCount` (or `pageCount: -1` for cursor APIs) through the table props.
   */
  pagination?: {
    pageSizeOptions?: number[]
    showTotal?: boolean
    siblingCount?: number
    showFirstLast?: boolean
    /** Use when the API's total lives somewhere other than TanStack's `rowCount`. */
    total?: number
    /** Use with `pageCount: -1` to stop a cursor-based list at its final response. */
    hasNextPage?: boolean
    labels?: Partial<PaginationControlsLabels>
    className?: string
  }
}

export function DataTable<TData extends RowData>({
  data,
  columns,
  onRowClick,
  renderSubComponent,
  className,
  rowClassName,
  style,
  loading,
  loadingMode = 'skeleton',
  loadingRowCount = 8,
  heightAuto,
  filtering,
  RowWrapper,
  translateHeader,
  clearFiltersLabel = 'Clear filters',
  loadingLabel = 'Loading',
  EmptyComponent = EmptyState,
  LoadingComponent,
  pagination,
  ...tableOptions
}: DataTableProps<TData>) {
  const table = useTable({ ...tableOptions, features: dataTableFeatures, data, columns })
  const showLoading = useDelayedLoading(!!loading, loadingMode === 'overlay' ? 0 : 150)
  const showSkeletonRows = loadingMode === 'skeleton' && !!loading && showLoading
  const showLoadingOverlay = loadingMode === 'overlay' && !!loading && showLoading
  const hasFilters = !!filtering && Object.keys(filtering.filters ?? {}).length > 0
  const clearFiltersButton = hasFilters ? (
    <Button
      variant="secondary"
      className="pointer-events-auto text-sm"
      onClick={() => filtering.updateFilters({})}
    >
      <SearchX className="h-4 w-4" />
      {clearFiltersLabel}
    </Button>
  ) : null

  return (
    <div className={cn('relative flex flex-col overflow-hidden rounded-panel bg-card', className)}>
      {/* The scroller gets its own relative box so the loading scrim can match it exactly:
          a fixed-height table hands the box the leftover space above the footer, and an
          auto-height one lets the rows size it. */}
      <div className={cn('relative', !heightAuto && 'min-h-0 flex-1')}>
        <div className={cn('isolate overflow-auto', !heightAuto && 'h-full')}>
          <TablePrimitive
            style={{ width: table.getTotalSize(), minWidth: '100%', ...style }}
            className="isolate border-separate"
            cellSpacing={0}
            border={0}
          >
            <TableHead table={table} filtering={filtering} translateHeader={translateHeader} />
            {!showSkeletonRows && (
              <TableBody
                table={table}
                onRowClick={onRowClick}
                rowClassName={rowClassName}
                RowWrapper={RowWrapper}
                renderSubComponent={renderSubComponent}
              />
            )}
            {showSkeletonRows && <TableLoadingBody table={table} rowCount={loadingRowCount} />}
          </TablePrimitive>
          {!loading && !table.getRowModel().rows.length && (
            <div className="pointer-events-none sticky inset-0 flex flex-col items-center gap-2">
              <EmptyComponent />
              {!pagination && clearFiltersButton}
            </div>
          )}
        </div>
        {/* A sibling of the scroller, not a child: inside it the scrim would scroll away with
            the rows and stop short of the table's real edges. */}
        {showLoadingOverlay && (
          <div className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center bg-background/55 backdrop-blur-[1px]">
            {LoadingComponent ? (
              <LoadingComponent />
            ) : (
              <span
                role="status"
                aria-live="polite"
                aria-busy="true"
                aria-label={loadingLabel}
                data-slot="data-table-loading"
                className="flex items-center gap-2 rounded-control border bg-card px-3 py-2 text-sm text-secondary-foreground shadow-md"
              >
                <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" />
                {loadingLabel}
              </span>
            )}
          </div>
        )}
      </div>
      {pagination && (
        <PaginationControls
          currentPage={(table.state.pagination?.pageIndex ?? 0) + 1}
          pageSize={table.state.pagination?.pageSize ?? pagination.pageSizeOptions?.[0] ?? 10}
          total={pagination.total ?? table.options.rowCount ?? table.getRowCount()}
          pageCount={table.getPageCount()}
          hasNextPage={pagination.hasNextPage}
          onPageChange={(page) => table.setPageIndex(page - 1)}
          onPageSizeChange={(size) => table.setPageSize(size)}
          pageSizeOptions={pagination.pageSizeOptions}
          showTotal={pagination.showTotal}
          siblingCount={pagination.siblingCount}
          showFirstLast={pagination.showFirstLast}
          labels={pagination.labels}
          className={pagination.className}
          leadingContent={clearFiltersButton}
        />
      )}
    </div>
  )
}

import type { Column, RowData } from '@tanstack/react-table'
import { ArrowDownWideNarrow, ArrowUpNarrowWide, Check, SearchIcon } from 'lucide-react'
import { useEffect, useState } from 'react'
import type { FieldValues } from 'react-hook-form'

import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { cn } from '@/lib/utils'

import { LoadingState } from '../loading-state'
import { OptionList } from '../option-list'
import type { DataTableFeatures } from '.'

export type FilterOption = { label: string; value: string }
export type FilterValues = Record<string, unknown>
type FilterUpdater<T> = T | ((old: T) => T)

type UseListHook = (
  params: Record<string, unknown>,
  options: Record<string, { enabled: boolean }>,
) => { data?: unknown; isLoading?: boolean }

type UseOptionsHook = (data: unknown) => FilterOption[]

export type ColumnFilterMeta = {
  key: string
  useList?: UseListHook
  useOptions?: UseOptionsHook
  options?: FilterOption[]
  multiple?: boolean
  transformer?: (filters?: FieldValues) => Promise<FieldValues | undefined>
  sort?: string
}

export type ColumnMeta = {
  filter?: ColumnFilterMeta
  headerClassName?: string
  cellClassName?: string
}

export type ColumnFilterLabels = {
  search: string
  reset: string
  noDataFound: string
}

export type FilterContext = {
  filters?: FilterValues
  updateFilters: (updater: FilterUpdater<FilterValues | undefined>) => void
  listParams?: Record<string, unknown>
  queryOptionKey?: string
  debounceMs?: number
  labels?: Partial<ColumnFilterLabels>
  translateOptionLabel?: (label: string) => string
  onError?: (error: unknown) => void
}

const DEFAULT_COLUMN_FILTER_LABELS: ColumnFilterLabels = {
  search: 'Search',
  reset: 'Reset',
  noDataFound: 'No data found',
}

const DEBOUNCE_DELAY_MS = 800

function useDebouncedValue<T>(value: T, delay: number) {
  const [debounced, setDebounced] = useState(value)
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}

export type ColumnFilterProps<TData extends RowData> = {
  // Bound to DataTable's private feature set so v9 exposes its sort methods.
  column: Column<DataTableFeatures, TData>
  filtering: FilterContext
}

export function ColumnFilter<TData extends RowData>({
  column,
  filtering,
}: ColumnFilterProps<TData>) {
  const { filters, updateFilters, onError } = filtering
  const labels: ColumnFilterLabels = { ...DEFAULT_COLUMN_FILTER_LABELS, ...filtering.labels }
  const [value, setValue] = useState('')
  const [optionValue, setOptionValue] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [open, setOpen] = useState(false)
  const meta = column.columnDef.meta as ColumnMeta | undefined
  const { key, transformer, useList, useOptions, options, multiple, sort } = meta?.filter ?? {}
  const filterValue = key ? (filters?.[key] as string | undefined) : undefined
  const ordering = filters?.ordering as string | undefined
  const isOptionsFilter = !!options || !!useList

  useEffect(() => {
    // The inputs mirror whatever the filter store currently holds.
    const v = filterValue || ''
    /* eslint-disable react-hooks/set-state-in-effect */
    setValue(v)
    setOptionValue(v.split(',').filter((o: string) => o))
    /* eslint-enable react-hooks/set-state-in-effect */
  }, [filterValue])

  async function transformedFilter(f?: FieldValues) {
    return transformer ? await transformer(f) : f
  }

  useEffect(() => {
    if (sort && ordering) {
      const isAsc = ordering === sort
      const isDesc = ordering === `-${sort}`
      if (isAsc || isDesc) {
        column.toggleSorting(!isAsc, false)
      }
    }
  }, [ordering, sort, column])

  // finally clears the busy flag even when the caller's transformer rejects; without it both
  // buttons stay disabled until unmount (the confirmed viz/cafm bug).
  async function handleUpdate() {
    if (!key) return
    setIsLoading(true)
    try {
      const f = await transformedFilter({ [key]: isOptionsFilter ? optionValue.join(',') : value })
      updateFilters((prev) => ({ ...prev, ...f }))
      setOpen(false)
    } catch (error) {
      onError?.(error)
    } finally {
      setIsLoading(false)
    }
  }

  async function handleReset() {
    if (!key) return
    setIsLoading(true)
    try {
      const f = await transformedFilter({ [key]: undefined })
      setValue('')
      setOptionValue([])
      // k !== key drops the filter even when the transformer returns {} or undefined.
      updateFilters((prev) =>
        Object.fromEntries(
          Object.entries(prev || {}).filter(
            ([k]) => k !== key && !Object.keys(f || {}).includes(k),
          ),
        ),
      )
      setOpen(false)
    } catch (error) {
      onError?.(error)
    } finally {
      setIsLoading(false)
    }
  }

  async function handleSort(isAsc: boolean) {
    if (!sort) return
    setIsLoading(true)
    try {
      const f = await transformedFilter({ ordering: isAsc ? sort : `-${sort}` })
      updateFilters((prev) => ({ ...prev, ...f }))
    } catch (error) {
      onError?.(error)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <div className="flex items-center justify-end gap-1">
        <PopoverTrigger>
          {!!key && (
            <SearchIcon
              className={cn('size-4 text-foreground hover:text-primary', value && 'text-primary')}
            />
          )}
        </PopoverTrigger>
        {!!sort && (
          <div
            data-testid="column-filter-sort"
            onClick={(e) => {
              e.preventDefault()
              const isAsc = column.getIsSorted() !== 'asc'
              column.toggleSorting(!isAsc)
              handleSort(isAsc)
            }}
          >
            {column.getIsSorted() === 'asc' ? (
              <ArrowUpNarrowWide className="size-4 cursor-pointer text-foreground hover:text-primary" />
            ) : (
              <ArrowDownWideNarrow className="size-4 cursor-pointer text-foreground hover:text-primary" />
            )}
          </div>
        )}
      </div>
      <PopoverContent align="end" className="mt-2 w-56 rounded-panel px-0 py-3 pt-1">
        <form
          onSubmit={(e) => {
            e.preventDefault()
            handleUpdate()
          }}
        >
          {!!options && (
            <OptionsInput
              value={optionValue}
              onValueChange={setOptionValue}
              options={options}
              multiple={multiple}
              labels={labels}
              translateOptionLabel={filtering.translateOptionLabel}
            />
          )}
          {!!useList && !!useOptions && (
            <SearchableOptionsInput
              value={optionValue}
              onValueChange={setOptionValue}
              useList={useList}
              useOptions={useOptions}
              multiple={multiple}
              labels={labels}
              filtering={filtering}
            />
          )}
          {!isOptionsFilter && (
            <div className="mt-2 px-3">
              <Input
                placeholder={labels.search}
                value={value}
                onChange={(event) => setValue(event.target.value)}
              />
            </div>
          )}
        </form>
        <div className="mx-3 mt-3 flex gap-2">
          <Button variant="secondary" className="flex-1" onClick={handleReset} disabled={isLoading}>
            {labels.reset}
          </Button>
          <Button className="flex-1" onClick={handleUpdate} disabled={isLoading}>
            {isLoading && <LoadingState variant="button" className="me-2 size-4" />}
            {labels.search}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

type OptionsProps = {
  options: FilterOption[]
  onValueChange: (value: string[]) => void
  value: string[]
  searchValue?: string
  onSearchValueChange?: (value: string) => void
  multiple?: boolean
  loading?: boolean
  labels: ColumnFilterLabels
  translateOptionLabel?: (label: string) => string
}

function OptionsInput({
  options,
  value,
  searchValue,
  onValueChange,
  onSearchValueChange,
  loading,
  multiple,
  labels,
  translateOptionLabel,
}: OptionsProps) {
  return (
    <OptionList
      placeholder={labels.search}
      searchValue={searchValue}
      onSearchValueChange={onSearchValueChange}
      empty={
        loading ? (
          <div className="flex justify-center">
            <LoadingState variant="button" />
          </div>
        ) : (
          labels.noDataFound
        )
      }
      items={options.map((option) => {
        const selected = value.includes(option.value)
        return {
          key: option.value,
          text: option.value,
          selected,
          onSelect: () =>
            selected
              ? onValueChange(value.filter((v) => v !== option.value))
              : onValueChange([...(multiple ? value : []), option.value]),
          content: (
            <>
              <Check className={cn('me-2 h-4 w-4', selected ? 'opacity-100' : 'opacity-0')} />
              {translateOptionLabel ? translateOptionLabel(option.label) : option.label}
            </>
          ),
        }
      })}
    />
  )
}

type SearchableOptionsProps = {
  useOptions: UseOptionsHook
  useList: UseListHook
  onValueChange: (value: string[]) => void
  value: string[]
  multiple?: boolean
  labels: ColumnFilterLabels
  filtering: FilterContext
}

function SearchableOptionsInput({
  useList,
  useOptions,
  onValueChange,
  value,
  multiple,
  labels,
  filtering,
}: SearchableOptionsProps) {
  const [search, setSearch] = useState('')
  const debouncedSearch = useDebouncedValue(search, filtering.debounceMs ?? DEBOUNCE_DELAY_MS)
  const { data, isLoading } = useList(
    {
      ...filtering.listParams,
      search: debouncedSearch,
      id: debouncedSearch ? undefined : value[0],
    },
    { [filtering.queryOptionKey ?? 'query']: { enabled: !!(debouncedSearch || value[0]) } },
  )
  return (
    <OptionsInput
      value={value}
      onValueChange={onValueChange}
      options={useOptions(data)}
      searchValue={search}
      onSearchValueChange={setSearch}
      loading={isLoading}
      multiple={multiple}
      labels={labels}
      translateOptionLabel={filtering.translateOptionLabel}
    />
  )
}

import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react'
import type { ReactNode } from 'react'

import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn } from '@/lib/utils'

export type PaginationControlsLabels = {
  showingResults: string
  noResults: string
  rowsPerPage: string
  firstPage: string
  previousPage: string
  nextPage: string
  lastPage: string
  page: (page: number) => string
  pageOf: (page: number, totalPages: number) => string
  morePages: string
}

const defaultLabels: PaginationControlsLabels = {
  showingResults: 'Showing {start}–{end} of {total}',
  noResults: 'No results',
  rowsPerPage: 'Rows per page',
  firstPage: 'Go to first page',
  previousPage: 'Go to previous page',
  nextPage: 'Go to next page',
  lastPage: 'Go to last page',
  page: (page) => `Go to page ${page}`,
  pageOf: (page, totalPages) => `Page ${page} of ${totalPages}`,
  morePages: 'More pages',
}

export type PaginationControlsProps = {
  /** One-based page number, matching the URL/API vocabulary used by app pages. */
  currentPage: number
  pageSize: number
  /** The total item count. Omit it for cursor APIs that do not report one. */
  total?: number
  /** A finite page count, or -1 when the API does not know where the list ends. */
  pageCount?: number
  /** Lets a cursor-based parent stop forward navigation without inventing a total. */
  hasNextPage?: boolean
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  pageSizeOptions?: number[]
  showTotal?: boolean
  /** Number of adjacent pages to show around the active page. */
  siblingCount?: number
  showFirstLast?: boolean
  labels?: Partial<PaginationControlsLabels>
  className?: string
  /** Optional content aligned with the result summary on the left side of the footer. */
  leadingContent?: ReactNode
}

const interpolate = (template: string, values: Record<string, number>) =>
  template.replace(/\{(start|end|total)\}/g, (_, key: 'start' | 'end' | 'total') =>
    String(values[key]),
  )

type PageItem = number | 'start-ellipsis' | 'end-ellipsis'

export function getPageItems(currentPage: number, pageCount: number, siblingCount = 1): PageItem[] {
  if (pageCount <= 0) return []
  const windowSize = siblingCount * 2 + 5
  if (pageCount <= windowSize) return Array.from({ length: pageCount }, (_, index) => index + 1)

  const start = Math.max(2, currentPage - siblingCount)
  const end = Math.min(pageCount - 1, currentPage + siblingCount)
  const items: PageItem[] = [1]

  if (start > 2) items.push('start-ellipsis')
  for (let page = start; page <= end; page += 1) items.push(page)
  if (end < pageCount - 1) items.push('end-ellipsis')

  items.push(pageCount)
  return items
}

export function PaginationControls({
  currentPage,
  pageSize,
  total,
  pageCount,
  hasNextPage,
  onPageChange,
  onPageSizeChange,
  pageSizeOptions = [10, 20, 50, 100],
  showTotal = true,
  siblingCount = 1,
  showFirstLast = true,
  labels,
  className,
  leadingContent,
}: PaginationControlsProps) {
  const copy = { ...defaultLabels, ...labels }
  const inferredPageCount = total === undefined ? undefined : Math.ceil(total / pageSize)
  const knownPageCount = pageCount === -1 ? undefined : (pageCount ?? inferredPageCount)
  const safePageCount = knownPageCount === undefined ? undefined : Math.max(knownPageCount, 1)
  const safeCurrentPage =
    safePageCount === undefined
      ? Math.max(currentPage, 1)
      : Math.min(Math.max(currentPage, 1), safePageCount)
  const start = total && total > 0 ? (safeCurrentPage - 1) * pageSize + 1 : 0
  const end = total === undefined ? 0 : Math.min(safeCurrentPage * pageSize, total)
  const canGoPrevious = safeCurrentPage > 1
  const canGoNext = hasNextPage ?? (safePageCount === undefined || safeCurrentPage < safePageCount)
  const pages =
    safePageCount === undefined ? [] : getPageItems(safeCurrentPage, safePageCount, siblingCount)

  return (
    <div
      className={cn(
        'flex flex-col gap-3 border-t bg-muted/[0.18] px-4 py-3 sm:flex-row sm:items-center sm:justify-between',
        className,
      )}
    >
      {(showTotal || leadingContent) && (
        <div className="order-2 flex items-center gap-3 text-sm text-muted-foreground sm:order-1">
          {showTotal && (
            <span>
              {total === undefined
                ? safePageCount === undefined
                  ? copy.page(safeCurrentPage)
                  : copy.pageOf(safeCurrentPage, safePageCount)
                : total > 0
                  ? interpolate(copy.showingResults, { start, end, total })
                  : copy.noResults}
            </span>
          )}
          {leadingContent}
        </div>
      )}
      <div className="order-1 flex flex-wrap items-center justify-between gap-3 sm:order-2 sm:justify-end">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <span className="text-sm text-muted-foreground">{copy.rowsPerPage}</span>
          <Select
            value={String(pageSize)}
            onValueChange={(value) => value !== null && onPageSizeChange(Number(value))}
          >
            <SelectTrigger size="sm" className="w-[70px]" aria-label={copy.rowsPerPage}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {pageSizeOptions.map((size) => (
                <SelectItem key={size} value={String(size)}>
                  {size}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <nav aria-label="Pagination" className="flex items-center gap-0.5">
          {showFirstLast && (
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={() => onPageChange(1)}
              disabled={!canGoPrevious}
              aria-label={copy.firstPage}
            >
              <ChevronsLeft className="rtl:rotate-180" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon-sm"
            onClick={() => onPageChange(safeCurrentPage - 1)}
            disabled={!canGoPrevious}
            aria-label={copy.previousPage}
          >
            <ChevronLeft className="rtl:rotate-180" />
          </Button>
          {pages.map((item) =>
            typeof item === 'number' ? (
              <Button
                key={item}
                variant={item === safeCurrentPage ? 'secondary' : 'ghost'}
                size="icon-sm"
                onClick={() => onPageChange(item)}
                aria-label={copy.page(item)}
                aria-current={item === safeCurrentPage ? 'page' : undefined}
              >
                {item}
              </Button>
            ) : (
              <span
                key={item}
                aria-label={copy.morePages}
                className="flex size-7 items-center justify-center text-sm text-muted-foreground"
              >
                …
              </span>
            ),
          )}
          {safePageCount === undefined && (
            <span className="px-1 text-sm tabular-nums text-muted-foreground">
              {safeCurrentPage}
            </span>
          )}
          <Button
            variant="ghost"
            size="icon-sm"
            onClick={() => onPageChange(safeCurrentPage + 1)}
            disabled={!canGoNext}
            aria-label={copy.nextPage}
          >
            <ChevronRight className="rtl:rotate-180" />
          </Button>
          {showFirstLast && safePageCount !== undefined && (
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={() => onPageChange(safePageCount)}
              disabled={!canGoNext}
              aria-label={copy.lastPage}
            >
              <ChevronsRight className="rtl:rotate-180" />
            </Button>
          )}
        </nav>
      </div>
    </div>
  )
}
